const HM = "data:image/png;base64,", PH = "data:image/jpeg;base64,", TP = "data:image/jpeg;base64,";
const S_M = 112000, RELIEF = 3000, UNIT = 100, S = S_M / UNIT, N = 512;   // map ~112 km wide (approx), relief ~3 km (illustrative)
const $ = id => document.getElementById(id);
const load = s => new Promise(r => { const i = new Image(); i.onload = () => r(i); i.src = s });
let ex = 3, lim = 10, mode = 'O', route = null, h = new Float32Array(N * N);
const hAt = (u, v) => { u = Math.min(.999, Math.max(0, u)) * (N - 1); v = Math.min(.999, Math.max(0, v)) * (N - 1); const x = u | 0, y = v | 0, fx = u - x, fy = v - y, a = h[y * N + x], b = h[y * N + x + 1], c = h[(y + 1) * N + x], d = h[(y + 1) * N + x + 1]; return (a * (1 - fx) + b * fx) * (1 - fy) + (c * (1 - fx) + d * fx) * fy };
