const P3 = (u, v, o = 0) => new THREE.Vector3((u - .5) * S, Y(u, v) + o, (v - .5) * S);
const START = [.42, .90], GOAL = [.45, .76];
const renderer = new THREE.WebGLRenderer({ canvas: $('c'), antialias: true }); renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
const scene = new THREE.Scene(); scene.background = new THREE.Color(0xc99b77); scene.fog = new THREE.Fog(0xc99b77, S * .35, S * 1.6);
const cam = new THREE.PerspectiveCamera(55, 1, .5, S * 4);
const sun = new THREE.DirectionalLight(0xfff0e0, 1.25); sun.position.set(-S, S * .35, -S * .6); scene.add(sun, new THREE.AmbientLight(0xd8b9a4, .75));
let mesh, tex = {}, orb = { th: .6, ph: .85, r: S * .95 }, look = { yaw: 0, pit: -.2 }, pos = new THREE.Vector3(), keys = {}, tubeG = new THREE.Group(); scene.add(tubeG);
function mkSlopeTex() {
  const c = document.createElement('canvas'); c.width = c.height = N; const g = c.getContext('2d'), im = g.createImageData(N, N), cell = S_M / N;
  for (let y = 0; y < N; y++)for (let x = 0; x < N; x++) {
    const x1 = Math.min(N - 1, x + 1), y1 = Math.min(N - 1, y + 1), x0 = Math.max(0, x - 1), y0 = Math.max(0, y - 1);
    const gx = (h[y * N + x1] - h[y * N + x0]) * RELIEF / (cell * (x1 - x0)), gy = (h[y1 * N + x] - h[y0 * N + x]) * RELIEF / (cell * (y1 - y0)); const s = Math.atan(Math.hypot(gx, gy)) * 57.3, t = Math.min(1, s / lim), i = (y * N + x) * 4;
    im.data.set(t < 1 ? [40 + 215 * t, 170 - 110 * t, 90 - 50 * t, 255] : [230, 40, 40, 255], i)
  }
  g.putImageData(im, 0, 0); const t = new THREE.CanvasTexture(c); t.anisotropy = 4; return t
}
function setLayer(k) { ['P', 'E', 'S'].forEach(a => $('l' + a).classList.toggle('on', a == k)); if (k == 'S') tex.S = mkSlopeTex(); mesh.material.map = tex[k]; mesh.material.needsUpdate = true }
function shape() { const p = mesh.geometry.attributes.position; for (let i = 0; i < p.count; i++) { const x = p.getX(i), z = p.getZ(i); p.setY(i, Y(x / S + .5, z / S + .5)) } p.needsUpdate = true; mesh.geometry.computeVertexNormals(); drawRoute() }
function astar() {
  const G = 160, m = new Float32Array(G * G), cs = S_M / G; for (let y = 0; y < G; y++)for (let x = 0; x < G; x++)m[y * G + x] = hAt(x / (G - 1), y / (G - 1)) * RELIEF;
  const idx = p => Math.round(p[1] * (G - 1)) * G + Math.round(p[0] * (G - 1)), s = idx(START), g = idx(GOAL), d = new Float32Array(G * G).fill(1e9), from = new Int32Array(G * G).fill(-1), H = [[0, s]]; d[s] = 0;
  const push = e => { H.push(e); let i = H.length - 1; while (i > 0) { const p = (i - 1) >> 1; if (H[p][0] <= H[i][0]) break;[H[p], H[i]] = [H[i], H[p]]; i = p } }, pop = () => { const t = H[0], l = H.pop(); if (H.length) { H[0] = l; let i = 0; for (; ;) { let a = 2 * i + 1, b = a + 1, k = i; if (a < H.length && H[a][0] < H[k][0]) k = a; if (b < H.length && H[b][0] < H[k][0]) k = b; if (k == i) break;[H[k], H[i]] = [H[i], H[k]]; i = k } } return t };
  const gx = g % G, gy = g / G | 0;
  while (H.length) {
    const [f, c] = pop(); if (c == g) break; const cx = c % G, cy = c / G | 0; if (f > d[c] + Math.hypot(cx - gx, cy - gy) * cs + 1) continue;
    for (let dy = -1; dy <= 1; dy++)for (let dx = -1; dx <= 1; dx++) {
      if (!dx && !dy) continue; const nx = cx + dx, ny = cy + dy; if (nx < 0 || ny < 0 || nx >= G || ny >= G) continue; const n = ny * G + nx, L = Math.hypot(dx, dy) * cs, sl = Math.atan(Math.abs(m[n] - m[c]) / L) * 57.3; if (sl > lim) continue;
      const nd = d[c] + L * (1 + 3 * (sl / lim) ** 2); if (nd < d[n]) { d[n] = nd; from[n] = c; push([nd + Math.hypot(nx - gx, ny - gy) * cs, n]) }
    }
  }
  if (from[g] < 0 && g != s) return null; const out = []; for (let c = g; c != -1; c = from[c])out.push([c % G / (G - 1), (c / G | 0) / (G - 1)]); return out.reverse()
}
function drawRoute() {
  tubeG.clear(); const r = $('bR').classList.contains('on'); route = astar();
  if (!route) { $('msg').textContent = 'No route under this slope limit. Raise the limit.'; return }
  let len = 0, mx = 0; for (let i = 1; i < route.length; i++) {
    const a = P3(...route[i - 1]), b = P3(...route[i]); len += Math.hypot((route[i][0] - route[i - 1][0]) * S_M, (route[i][1] - route[i - 1][1]) * S_M);
    mx = Math.max(mx, Math.atan(Math.abs(hAt(...route[i]) - hAt(...route[i - 1])) * RELIEF / (Math.hypot((route[i][0] - route[i - 1][0]) * S_M, (route[i][1] - route[i - 1][1]) * S_M) || 1)) * 57.3)
  }
  $('msg').textContent = `Route ${(len / 1000).toFixed(1)} km, steepest step ${mx.toFixed(1)}°, about ${(len / 1000 / 4).toFixed(1)} h at 4 km/h.`;
  if (!r) return; const pts = route.filter((_, i) => i % 3 == 0 || i == route.length - 1).map(p => P3(p[0], p[1], 1.2));
  tubeG.add(new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), pts.length * 3, .9, 6), new THREE.MeshBasicMaterial({ color: 0xffd34d })));
  [[START, 0xe0743c], [GOAL, 0xbfe9f5]].forEach(([p, c]) => { const a = P3(...p); const m = new THREE.Mesh(new THREE.ConeGeometry(2.2, 9, 12), new THREE.MeshBasicMaterial({ color: c })); m.rotation.x = Math.PI; m.position.set(a.x, a.y + 8, a.z); tubeG.add(m) })
}
const tags = [['Landing site', START], ['Ice edge (target)', GOAL]].map(([t, p]) => { const e = document.createElement('div'); e.className = 'tag'; e.textContent = t; document.body.appendChild(e); return [e, p] });
function setMode(m) { mode = m; $('mO').classList.toggle('on', m == 'O'); $('mW').classList.toggle('on', m == 'W'); $('fwd').style.display = (m == 'W' && matchMedia('(pointer:coarse)').matches) ? 'block' : 'none'; if (m == 'W') goStart() }
function goStart() { mode != 'W' && setMode('W'); const a = P3(...START), b = P3(...(route && route[Math.min(8, route.length - 1)] || GOAL)); pos.set(a.x, 0, a.z); look.yaw = Math.atan2(b.x - a.x, -(b.z - a.z)); look.pit = -.12 }
let drag = null; const cv = $('c');
cv.addEventListener('pointerdown', e => { drag = [e.clientX, e.clientY]; cv.setPointerCapture(e.pointerId) }); cv.addEventListener('pointerup', () => drag = null);
cv.addEventListener('pointermove', e => {
  if (!drag) return; const dx = e.clientX - drag[0], dy = e.clientY - drag[1]; drag = [e.clientX, e.clientY];
  if (mode == 'O') { orb.th -= dx * .006; orb.ph = Math.min(1.5, Math.max(.12, orb.ph - dy * .006)) } else { look.yaw += dx * .005; look.pit = Math.max(-1.3, Math.min(1.3, look.pit - dy * .005)) }
});
cv.addEventListener('wheel', e => { e.preventDefault(); orb.r = Math.min(S * 1.6, Math.max(S * .08, orb.r * (1 + e.deltaY * .001))) }, { passive: false });
addEventListener('keydown', e => keys[e.key.toLowerCase()] = 1); addEventListener('keyup', e => keys[e.key.toLowerCase()] = 0);
$('fwd').addEventListener('pointerdown', () => keys.w = 1); $('fwd').addEventListener('pointerup', () => keys.w = 0);
$('mO').onclick = () => setMode('O'); $('mW').onclick = () => setMode('W'); $('bG').onclick = goStart;
$('lP').onclick = () => setLayer('P'); $('lE').onclick = () => setLayer('E'); $('lS').onclick = () => setLayer('S');
$('bR').onclick = e => { e.target.classList.toggle('on'); e.target.textContent = e.target.classList.contains('on') ? 'Route on' : 'Route off'; drawRoute() };
$('rE').oninput = e => { ex = +e.target.value; $('vE').textContent = ex + '×'; shape() };
$('rL').oninput = e => { lim = +e.target.value; $('vL').textContent = lim + '°'; drawRoute(); if (mesh.material.map == tex.S) setLayer('S') };
function resize() { renderer.setSize(innerWidth, innerHeight, false); cam.aspect = innerWidth / innerHeight; cam.updateProjectionMatrix() } addEventListener('resize', resize); resize();
const clock = new THREE.Clock();
function frame() {
  requestAnimationFrame(frame); const dt = Math.min(.05, clock.getDelta());
  if (mode == 'O') { cam.position.set(Math.sin(orb.th) * Math.sin(orb.ph) * orb.r, Math.cos(orb.ph) * orb.r, Math.cos(orb.th) * Math.sin(orb.ph) * orb.r); cam.lookAt(0, 0, 0) }
  else {
    const sp = (keys.shift ? 160 : 40) * dt, f = (keys.w || keys.arrowup ? 1 : 0) - (keys.s || keys.arrowdown ? 1 : 0), r = (keys.d || keys.arrowright ? 1 : 0) - (keys.a || keys.arrowleft ? 1 : 0);
    pos.x += (Math.sin(look.yaw) * f + Math.cos(look.yaw) * r) * sp; pos.z += (-Math.cos(look.yaw) * f + Math.sin(look.yaw) * r) * sp; pos.x = Math.max(-S / 2 + 2, Math.min(S / 2 - 2, pos.x)); pos.z = Math.max(-S / 2 + 2, Math.min(S / 2 - 2, pos.z));
    pos.y = Y(pos.x / S + .5, pos.z / S + .5) + 4; cam.position.copy(pos); cam.rotation.set(look.pit, -look.yaw, 0, 'YXZ')
  }
  tags.forEach(([e, p]) => { const v = P3(...p, 14).project(cam); const ok = v.z < 1 && Math.abs(v.x) < 1 && Math.abs(v.y) < 1; e.style.display = ok ? 'block' : 'none'; e.style.left = (v.x * .5 + .5) * innerWidth + 'px'; e.style.top = (-v.y * .5 + .5) * innerHeight + 'px' });
  const u = mode == 'W' ? pos.x / S + .5 : .5, v = mode == 'W' ? pos.z / S + .5 : .5;
  if (mode == 'W') {
    const d = Math.hypot((u - GOAL[0]) * S_M, (v - GOAL[1]) * S_M) / 1000, hh = hAt(u, v) * RELIEF, hs = hAt(u + .003, v) * RELIEF - hAt(u - .003, v) * RELIEF, vs = hAt(u, v + .003) * RELIEF - hAt(u, v - .003) * RELIEF;
    $('hud').innerHTML = `Surface view<br>Height above lowest point <b>${hh.toFixed(0)} m</b><br>Slope here <b>${(Math.atan(Math.hypot(hs, vs) / (.006 * S_M)) * 57.3).toFixed(1)}°</b><br>Straight line to ice <b>${d.toFixed(1)} km</b><br><span style="color:var(--mute)">WASD / arrows move, Shift is fast</span>`
  }
  else $('hud').innerHTML = `Orbit view<br>Map width <b>about 110 km</b><br>Drag to rotate, scroll to zoom`;
  renderer.render(scene, cam)
}
Promise.all([load(HM), load(PH), load(TP)]).then(([hm, ph, tp]) => {
  const c = document.createElement('canvas'); c.width = c.height = N; const g = c.getContext('2d'); g.drawImage(hm, 0, 0); const d = g.getImageData(0, 0, N, N).data; for (let i = 0; i < N * N; i++)h[i] = (d[i * 4] * 256 + d[i * 4 + 1]) / 65535;
  const mk = i => { const t = new THREE.Texture(i); t.anisotropy = 8; t.needsUpdate = true; return t }; tex.P = mk(ph); tex.E = mk(tp);
  const geo = new THREE.PlaneGeometry(S, S, 255, 255); geo.rotateX(-Math.PI / 2); mesh = new THREE.Mesh(geo, new THREE.MeshStandardMaterial({ map: tex.P, roughness: 1, metalness: 0 })); scene.add(mesh);
  shape(); frame()
});
